def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    def orbit(r, c):
        points = set()
        for _ in range(4):
            points.add((r, c))
            points.add((c, n - 1 - r))
            r, c = c, n - 1 - r
        return points
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                vals = [grid[rr][cc] for rr, cc in orbit(r, c) if grid[rr][cc] != 2]
                if vals:
                    out[r][c] = max(set(vals), key=vals.count)
    return out
